#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <omp.h>

#if defined(__SSE2__)
#include <emmintrin.h>
#endif

static bool validate_scalar_until(const unsigned char *bytes, size_t length,
                                  size_t &index, size_t stop) {
  const uint64_t high_bits = UINT64_C(0x8080808080808080);

  while (index < stop) {
    if (bytes[index] < 0x80) {
      if (length - index >= sizeof(uint64_t)) {
        uint64_t word;
        std::memcpy(&word, bytes + index, sizeof(word));
        if ((word & high_bits) == 0) {
          index += sizeof(word);
          continue;
        }
      }
      do {
        ++index;
      } while (index < stop && bytes[index] < 0x80);
      if (index >= stop) {
        return true;
      }
    }

    unsigned char byte1 = bytes[index++];
    if (byte1 < 0xE0) {
      if (byte1 < 0xC2 || index == length ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    } else if (byte1 < 0xF0) {
      if (length - index < 2) {
        return false;
      }
      unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80 ||
          (byte1 == 0xE0 && byte2 < 0xA0) ||
          (byte1 == 0xED && byte2 >= 0xA0) ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    } else {
      if (byte1 > 0xF4 || length - index < 3) {
        return false;
      }
      unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80 ||
          (byte1 == 0xF0 && byte2 < 0x90) ||
          (byte1 == 0xF4 && byte2 > 0x8F) ||
          (bytes[index++] & 0xC0) != 0x80 ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    }
  }
  return true;
}

static bool validate_utf8(const char *b, size_t length) {
  const unsigned char *bytes = (const unsigned char *)b;
  size_t index = 0;

  while (index < length) {
#if defined(__SSE2__)
    if (length - index >= 16) {
      const __m128i block =
          _mm_loadu_si128(reinterpret_cast<const __m128i *>(bytes + index));
      if (_mm_movemask_epi8(block) == 0) {
        index += 16;
        continue;
      }

      // The block is mixed or non-ASCII; validate it with bounded scalar logic.
      const size_t block_end = index + 16;
      if (!validate_scalar_until(bytes, length, index, block_end)) {
        return false;
      }
#else
    {
#endif
      if (!validate_scalar_until(bytes, length, index, length)) {
        return false;
      }
#if defined(__SSE2__)
    }
#endif
  }
  return true;
}

extern "C" void run(const void *input1, const void *input2, void *output, int n, int parameter, int threads) {
  *(uint32_t *)output = validate_utf8((const char *)input1, n);
}
